import { z } from 'zod';

/**
 * Owns the canonical UUID wire representation shared by every PSD EOC domain
 * module. IDs are generated by trusted application or database code and remain
 * stable for the lifetime of the referenced record.
 */
export const UuidSchema = z.string().uuid();

/** Canonical UUID value inferred from {@link UuidSchema}. */
export type Uuid = z.infer<typeof UuidSchema>;

/**
 * Roles a signed-in person can hold.
 *
 * This lives in the dependency-free module because two domains need it and
 * neither can import the other: identity describes who a person is, and group
 * describes which access group grants them a role. Defining it here keeps the
 * single source of truth without an import cycle — `identity` re-exports it, so
 * every existing importer is unaffected.
 */
export const RoleSchema = z.enum(['staff', 'admin', 'partner']);

/** User role inferred from {@link RoleSchema}. */
export type Role = z.infer<typeof RoleSchema>;

/**
 * Roles a district Google identity can hold. An access group grants one of
 * these and never `partner`: a partner is a person outside the district who
 * signs in through a separate identity provider and is let in only by a
 * partner admission, so no group membership can make somebody a partner and
 * no partner admission can make somebody staff.
 */
export const StaffRoleSchema = RoleSchema.exclude(['partner']);

/** Staff-identity role inferred from {@link StaffRoleSchema}. */
export type StaffRole = z.infer<typeof StaffRoleSchema>;

/**
 * True when a role set never mixes `partner` with a staff role. A partner holds
 * `partner` alone; staff and administrators never hold it. The database and the
 * server's access decisions enforce the same rule independently.
 */
export function isExclusiveRoleSet(roles: readonly Role[]): boolean {
  return !roles.includes('partner') || roles.length === 1;
}

/**
 * Owns the canonical absolute timestamp wire representation. Domain records
 * use immutable ISO 8601 strings at package boundaries rather than `Date`
 * objects, so REST, MCP, mobile, and persistence callers share one format.
 */
export const TimestampSchema = z.string().datetime({ offset: true });

/** Canonical timestamp value inferred from {@link TimestampSchema}. */
export type Timestamp = z.infer<typeof TimestampSchema>;

/**
 * Owns HTTPS-only transient links returned to clients for uploads, authorized
 * reads, and generated exports. Arbitrary URL schemes and plaintext HTTP are
 * rejected so a server result cannot become an executable or insecure link.
 */
export const HttpsUrlSchema = z
  .string()
  .url()
  .max(8_192)
  .refine(
    (value) => {
      try {
        return new URL(value).protocol === 'https:';
      } catch {
        return false;
      }
    },
    {
      message: 'Client-facing transient URLs must use HTTPS.',
    },
  );

/** HTTPS-only client link inferred from its schema. */
export type HttpsUrl = z.infer<typeof HttpsUrlSchema>;

/**
 * Owns positive, monotonically increasing version numbers used by immutable
 * roster, audience, and event-type revisions.
 */
export const VersionSchema = z.number().int().positive();

/** Canonical positive version inferred from {@link VersionSchema}. */
export type Version = z.infer<typeof VersionSchema>;

/** Returns true only when every string in a collection is unique. */
export function hasUniqueStrings(values: readonly string[]): boolean {
  return new Set(values).size === values.length;
}

/** Returns true when `later` is chronologically at or after `earlier`. */
export function isAtOrAfter(later: string, earlier: string): boolean {
  return Date.parse(later) >= Date.parse(earlier);
}

/** Administrator-given display name for an agent identity or agent key. */
export const AgentApiKeyDisplayNameSchema = z.string().trim().min(1).max(160);

/** Public, non-secret prefix that identifies one agent API key. */
export const AgentApiKeyPrefixSchema = z
  .string()
  .trim()
  .min(8)
  .max(24)
  .regex(/^[A-Za-z0-9_-]+$/u);

/**
 * Owns the two key-summary fields that identify an agent key to a human
 * reader: the name an administrator gave the key and its public prefix. Draft
 * review shows these for an agent author instead of a bare UUID. It lives here
 * so event-type contracts can use it without importing the agent-key module.
 */
export const AgentApiKeyLabelSchema = z
  .object({
    displayName: AgentApiKeyDisplayNameSchema,
    keyPrefix: AgentApiKeyPrefixSchema,
  })
  .strict()
  .readonly();

/** Human-readable agent key label inferred from its schema. */
export type AgentApiKeyLabel = z.infer<typeof AgentApiKeyLabelSchema>;
